import http.server as h
class H(h.SimpleHTTPRequestHandler):
    extensions_map = {**h.SimpleHTTPRequestHandler.extensions_map, '.js': 'text/javascript', '.webmanifest': 'application/manifest+json'}
    def end_headers(self):
        self.send_header('Cache-Control', 'no-store')
        super().end_headers()
h.ThreadingHTTPServer(('127.0.0.1', 8162), H).serve_forever()
